// ── Shell component ──
function Shell({
  cx,
  cy,
  rx,
  ry,
}: {
  cx: number;
  cy: number;
  rx: number;
  ry: number;
}) {
  return (
    <g>
      <ellipse cx={cx} cy={cy} rx={rx} ry={ry - 4} fill={P} />
      <ellipse
        cx={cx}
        cy={cy - 10}
        rx={rx * 0.48}
        ry={ry * 0.44}
        stroke={PM}
        strokeWidth="1.8"
        fill="none"
        opacity="0.45"
      />
      <line
        x1={cx - rx * 0.35}
        y1={cy - 6}
        x2={cx - rx * 0.7}
        y2={cy + ry * 0.38}
        stroke={PM}
        strokeWidth="1.8"
        opacity="0.35"
      />
      <line
        x1={cx + rx * 0.35}
        y1={cy - 6}
        x2={cx + rx * 0.7}
        y2={cy + ry * 0.38}
        stroke={PM}
        strokeWidth="1.8"
        opacity="0.35"
      />
      <ellipse
        cx={cx - 8}
        cy={cy - 14}
        rx={12}
        ry={8}
        fill={PL}
        opacity="0.12"
      />
      {RB.map((c, i) => (
        <path
          key={i}
          d={`M${cx - rx + 8 + i * 2} ${cy + 2 + i * 2.5} Q${cx} ${cy - 18 + i * 2.5} ${cx + rx - 8 - i * 2} ${cy + 2 + i * 2.5}`}
          stroke={c}
          strokeWidth="2.5"
          fill="none"
          strokeLinecap="round"
          opacity="0.65"
        />
      ))}
    </g>
  );
}

// ── Glasses component ──
function Glasses({
  cx,
  cy,
  rot,
}: {
  cx: number;
  cy: number;
  rot?: number;
}) {
  const t = rot ? `rotate(${rot} ${cx} ${cy})` : undefined;
  return (
    <g transform={t}>
      <rect
        x={cx - 22}
        y={cy - 8}
        width="20"
        height="15"
        rx="4.5"
        stroke={W}
        strokeWidth="2.6"
        fill="rgba(255,255,255,0.08)"
      />
      <rect
        x={cx + 2}
        y={cy - 8}
        width="20"
        height="15"
        rx="4.5"
        stroke={W}
        strokeWidth="2.6"
        fill="rgba(255,255,255,0.08)"
      />
      <path
        d={`M${cx - 2} ${cy - 2} C${cx - 1} ${cy - 4}, ${cx + 1} ${cy - 4}, ${cx + 2} ${cy - 2}`}
        stroke={W}
        strokeWidth="2"
        fill="none"
      />
      <line
        x1={cx - 22}
        y1={cy - 2}
        x2={cx - 28}
        y2={cy - 4}
        stroke={W}
        strokeWidth="2"
        strokeLinecap="round"
      />
      <line
        x1={cx + 22}
        y1={cy - 2}
        x2={cx + 28}
        y2={cy - 4}
        stroke={W}
        strokeWidth="2"
        strokeLinecap="round"
      />
    </g>
  );
}

