// ── Rainbow Divider ──
function Rainbow({ width = 108 }: { width?: number }) {
  const gap = 3;
  const w = (width - gap * 5) / 6;
  return (
    <div style={{ display: "flex", gap, justifyContent: "center" }}>
      {RB.map((c, i) => (
        <div
          key={i}
          style={{
            width: w,
            height: 3,
            background: c,
            borderRadius: 2,
          }}
        />
      ))}
    </div>
  );
}

// ── Language Selector ──
function LanguageSwitcher() {
  const locale = useLocale();
  const router = useRouter();
  const pathname = usePathname();

  return (
    <div
      style={{
        position: "absolute",
        top: 20,
        right: 24,
        display: "flex",
        gap: 6,
      }}
    >
      {locales.map((l) => (
        <button
          key={l}
          onClick={() => router.replace(pathname, { locale: l })}
          style={{
            padding: "5px 10px",
            borderRadius: 8,
            border:
              l === locale
                ? `1.5px solid ${P}`
                : "1.5px solid rgba(255,255,255,0.08)",
            background:
              l === locale ? `${P}22` : "rgba(255,255,255,0.03)",
            color:
              l === locale ? PL : "rgba(255,255,255,0.3)",
            fontSize: 12,
            fontWeight: l === locale ? 700 : 400,
            cursor: "pointer",
            fontFamily: "inherit",
            textTransform: "uppercase",
            transition: "all 0.2s",
          }}
        >
          {l}
        </button>
      ))}
    </div>
  );
}

// ── Main Landing Page ──
export default function Landing() {
  const t = useTranslations();
  const [email, setEmail] = useState("");
  const [state, setState] = useState<"idle" | "loading" | "done" | "error">(
    "idle"
  );
  const [show, setShow] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setShow(true), 100);
    return () => clearTimeout(timer);
  }, []);

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email.includes("@")) return;
    setState("loading");

    try {
      const res = await fetch("/api/waitlist", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email }),
      });
      if (res.ok) {
        setState("done");
      } else {
        setState("error");
      }
    } catch {
      setState("error");
    }
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        background: BG,
        fontFamily: "'Inter', -apple-system, sans-serif",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        padding: "40px 24px",
        position: "relative",
        overflow: "hidden",
      }}
    >
      <style>{`
        @keyframes wig { 0%,100% { transform: rotate(0deg); } 25% { transform: rotate(2deg); } 75% { transform: rotate(-2deg); } }
        @keyframes glow { 0%,100% { opacity: 0.08; } 50% { opacity: 0.14; } }
        * { box-sizing: border-box; margin: 0; padding: 0; }
        ::selection { background: ${P}88; color: white; }
        input::placeholder { color: rgba(255,255,255,0.2); }
        input:focus { border-color: ${P} !important; box-shadow: 0 0 0 3px ${P}33; outline: none; }
      `}</style>

      <LanguageSwitcher />

      {/* Background glow */}
      <div
        style={{
          position: "absolute",
          top: "30%",
          left: "50%",
          transform: "translateX(-50%)",
          width: 500,
          height: 500,
          borderRadius: "50%",
          background: `radial-gradient(circle, ${P}10, transparent 70%)`,
          filter: "blur(80px)",
          pointerEvents: "none",
          animation: "glow 6s ease-in-out infinite",
        }}
      />

      {/* Content */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: 0,
          maxWidth: 400,
          width: "100%",
          opacity: show ? 1 : 0,
          transform: show ? "translateY(0)" : "translateY(20px)",
          transition: "opacity 1.2s ease-out, transform 1.2s ease-out",
        }}
      >
        {/* Q — waiting pose */}
        <div
          style={{
            animation: "wig 3s ease-in-out infinite",
            marginBottom: 28,
          }}
        >
          <QWaiting size={140} />
        </div>

        {/* Tagline */}
        <p
          style={{
            color: "rgba(255,255,255,0.38)",
            fontSize: 17,
            lineHeight: 1.7,
            textAlign: "center",
            marginBottom: 36,
            maxWidth: 340,
            fontWeight: 400,
          }}
        >
          {t("hero.tagline")}
          <br />
          {t("hero.subtitle")}
        </p>

        {/* strQ.app wordmark */}
        <div style={{ textAlign: "center", marginBottom: 6 }}>
          <span
            style={{
              fontSize: 32,
              fontWeight: 800,
              color: W,
              letterSpacing: 1,
              fontFamily: "'Inter', -apple-system, sans-serif",
            }}
          >
            str
            <span style={{ color: PL, fontSize: 38, fontWeight: 900 }}>
              Q
            </span>
            <span
              style={{
                color: "rgba(255,255,255,0.3)",
                fontWeight: 600,
              }}
            >
              .app
            </span>
          </span>
        </div>

        {/* Rainbow */}
        <div style={{ marginBottom: 36 }}>
          <Rainbow width={108} />
        </div>

        {/* Waitlist form or confirmation */}
        {state === "done" ? (
          <div
            style={{
              textAlign: "center",
              opacity: 1,
              transition: "opacity 0.6s ease-out",
            }}
          >
            <div
              style={{
                color: W,
                fontWeight: 600,
                fontSize: 15,
                marginBottom: 6,
              }}
            >
              {t("waitlist.success")}
            </div>
          </div>
        ) : (
          <form
            onSubmit={submit}
            style={{ display: "flex", gap: 8, width: "100%" }}
          >
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder={t("waitlist.placeholder")}
              style={{
                flex: 1,
                padding: "13px 16px",
                borderRadius: 12,
                border: "1.5px solid rgba(255,255,255,0.08)",
                background: "rgba(255,255,255,0.04)",
                color: W,
                fontSize: 15,
                fontFamily: "inherit",
              }}
            />
            <button
              type="submit"
              disabled={state === "loading"}
              style={{
                padding: "13px 22px",
                borderRadius: 12,
                border: "none",
                background: P,
                color: W,
                fontSize: 15,
                fontWeight: 700,
                cursor: "pointer",
                fontFamily: "inherit",
                opacity: state === "loading" ? 0.5 : 1,
                transition: "opacity 0.2s",
              }}
            >
              {state === "loading" ? "..." : t("waitlist.button")}
            </button>
          </form>
        )}

        {state === "error" && (
          <p
            style={{
              color: "#E74C3C",
              fontSize: 13,
              marginTop: 8,
              textAlign: "center",
            }}
          >
            {t("waitlist.error")}
          </p>
        )}

        {/* Footer */}
        <div
          style={{
            marginTop: 48,
            textAlign: "center",
            color: "rgba(255,255,255,0.12)",
            fontSize: 12,
            lineHeight: 1.6,
          }}
        >
          {t("footer.privacy")}
          <br />
          {t("footer.copyright", { year: new Date().getFullYear() })}
        </div>
      </div>
    </div>
  );
}
